package com.luci.pianoroom;
import android.app.*;import android.content.*;import android.content.res.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.widget.*;
/** Visual editor. The service owns audio; this window only owns GPU/UI state. */
public final class PianoModelDialog extends Dialog {
 private static final int BG=RoomTheme.BACKGROUND,CARD=RoomTheme.SURFACE,FG=RoomTheme.INK,MUTED=RoomTheme.MUTED,TEAL=RoomTheme.GREEN;
 private static PianoMesh cachedMesh;private final Activity activity;private final PianoService service;private final Runnable changed;
 private Piano3DView piano;private Indicator indicator;private LinearLayout controls;private TextView detail;private int channel,part;private boolean inside,paused,closed,rebuilding;private float yaw,pitch,distance;
 private interface Set{void value(int n);}
 public PianoModelDialog(Activity a,PianoService s,int ch,Runnable changed){super(a);activity=a;service=s;channel=Math.max(0,Math.min(4,ch));this.changed=changed;part=Math.max(0,Math.min(5,s.prefs.getInt("piano3dPart",0)));yaw=s.prefs.getFloat("piano3dYaw",1.1f);pitch=s.prefs.getFloat("piano3dPitch",.48f);distance=s.prefs.getFloat("piano3dDistance",6.8f);inside=s.prefs.getBoolean("piano3dInterior",false);requestWindowFeature(Window.FEATURE_NO_TITLE);setOnDismissListener(d->{closed=true;stopView();saveView();if(changed!=null)changed.run();});}
 public void open(){show();relayout();}
 public void dispose(){closed=true;stopView();saveView();setOnDismissListener(null);dismiss();}
 private int dp(int n){return Math.round(n*activity.getResources().getDisplayMetrics().density);}
 private ChannelSettings settings(){return channel==4?service.synth.yamahaEffects:service.synth.channels[channel];}
 private boolean usable(){return !closed&&!service.closed&&service.synth!=null;}
 private void saveView(){if(service.closed)return;service.prefs.edit().putInt("piano3dPart",part).putFloat("piano3dYaw",yaw).putFloat("piano3dPitch",pitch).putFloat("piano3dDistance",distance).putBoolean("piano3dInterior",inside).apply();}
 private void captureCamera(){if(piano!=null){PianoCamera.State state=piano.state;yaw=state.yaw;pitch=state.pitch;distance=state.distance;}}
 private void stopView(){if(piano!=null){captureCamera();piano.onPause();piano=null;}}
 public void pause(){paused=true;if(piano!=null)piano.onPause();captureCamera();saveView();}
 public void resume(){paused=false;if(piano!=null)piano.onResume();}
 private LinearLayout column(){LinearLayout l=new LinearLayout(activity);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private LinearLayout row(){LinearLayout l=new LinearLayout(activity);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 private TextView text(String str,int size,int color){TextView t=new TextView(activity);t.setText(str);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(3),0,dp(5));return t;}
 private Button button(String str,Runnable action){Button b=new Button(activity);b.setText(str);b.setTextSize(12);b.setAllCaps(false);b.setMinWidth(dp(48));b.setMinimumHeight(dp(48));b.setMaxLines(2);b.setPadding(dp(8),dp(6),dp(8),dp(6));b.setTextColor(RoomTheme.WHITE);b.setBackgroundTintList(ColorStateList.valueOf(TEAL));b.setOnClickListener(v->{if(usable())action.run();});return b;}
 private void buttons(LinearLayout target,Button... bs){LinearLayout r=row();for(Button b:bs){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(2),0,dp(2),0);r.addView(b,p);}target.addView(r);}
 private void spinner(LinearLayout target,String[] items,int current,Set fn){Spinner sp=new Spinner(activity);ArrayAdapter<String> ad=new ArrayAdapter<>(activity,android.R.layout.simple_spinner_item,items);ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);sp.setAdapter(ad);sp.setSelection(current);sp.setBackgroundTintList(ColorStateList.valueOf(TEAL));target.addView(sp,new LinearLayout.LayoutParams(-1,dp(48)));sp.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(!rebuilding&&usable()&&n!=current)fn.value(n);}});}
 private void check(LinearLayout target,String label,boolean value,Runnable action){CheckBox c=new CheckBox(activity);c.setText(label);c.setTextSize(13);c.setTextColor(FG);c.setButtonTintList(ColorStateList.valueOf(TEAL));c.setChecked(value);target.addView(c);c.setOnCheckedChangeListener((b,on)->{if(!rebuilding&&usable())action.run();});}
 private void slider(String label,int max,int value,Set fn){TextView t=text(label+" · "+value,13,FG);controls.addView(t);SeekBar b=new SeekBar(activity);b.setMax(max);b.setProgress(value);b.setContentDescription(label);b.setThumbTintList(ColorStateList.valueOf(TEAL));b.setProgressTintList(ColorStateList.valueOf(TEAL));controls.addView(b,new LinearLayout.LayoutParams(-1,dp(48)));b.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){saveView();}public void onProgressChanged(SeekBar s,int n,boolean user){t.setText(label+" · "+n);if(user&&usable()){fn.value(n);service.channelEffects(channel);sync();}}});}
 public void relayout(){if(closed||!isShowing())return;stopView();rebuilding=true;Window w=getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setStatusBarColor(BG);w.setNavigationBarColor(BG);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_NOTHING);}LinearLayout root=column();root.setBackgroundColor(BG);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(dp(12)+in.getSystemWindowInsetLeft(),dp(8)+in.getSystemWindowInsetTop(),dp(12)+in.getSystemWindowInsetRight(),dp(8)+in.getSystemWindowInsetBottom());return in.consumeSystemWindowInsets();});LinearLayout header=row();TextView title=text("PIANO VIRTUAL · 0.26 Bibliotecas",16,TEAL);title.setTypeface(null,Typeface.BOLD);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button back=button("Voltar",this::dismiss);back.setOnClickListener(v->dismiss());header.addView(back,new LinearLayout.LayoutParams(dp(76),dp(48)));root.addView(header);root.addView(text("Mesa e Yamaha USB • gire, aproxime e toque nas partes",12,MUTED));
  LinearLayout workspace=new LinearLayout(activity);boolean lateral=activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE;workspace.setOrientation(lateral?0:1);root.addView(workspace,new LinearLayout.LayoutParams(-1,0,1));FrameLayout stage=new FrameLayout(activity);stage.setBackgroundColor(BG);LinearLayout.LayoutParams stageParams=lateral?new LinearLayout.LayoutParams(0,-1,1.6f):new LinearLayout.LayoutParams(-1,0,1.1f);stageParams.setMargins(0,0,dp(lateral?10:0),dp(lateral?0:8));workspace.addView(stage,stageParams);
  try{if(cachedMesh==null)cachedMesh=PianoMesh.read(activity.getAssets().open("piano3d.pr3d"));piano=new Piano3DView(activity,cachedMesh,new Piano3DView.Listener(){public void selected(int p){select(p);}public void cameraChanged(){captureCamera();if(indicator!=null)indicator.invalidate();}public void error(String message){if(!closed){TextView error=text(message,13,TEAL);error.setBackgroundColor(BG);stage.addView(error,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));}}});stage.addView(piano,new FrameLayout.LayoutParams(-1,-1));piano.camera(yaw,pitch,distance);indicator=new Indicator();stage.addView(indicator,new FrameLayout.LayoutParams(-1,-1));if(paused)piano.onPause();}catch(Exception e){stage.addView(text("Modelo indisponível. Os ajustes de áudio continuam abaixo.",14,MUTED));}
  ScrollView scroll=new ScrollView(activity);scroll.setFillViewport(false);controls=column();controls.setPadding(dp(12),dp(8),dp(12),dp(12));GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{0xfff9f8f2,CARD});bg.setCornerRadius(dp(16));controls.setBackground(bg);scroll.addView(controls);workspace.addView(scroll,lateral?new LinearLayout.LayoutParams(0,-1,1):new LinearLayout.LayoutParams(-1,0,1));setContentView(root);if(w!=null)w.setLayout(-1,-1);rebuilding=false;buildControls();sync();
 }
 private void select(int p){if(!usable())return;part=p;if(p==2||p==3)inside=true;if(p==0||p==1)inside=false;buildControls();sync();saveView();}
 private String[] channelNames(){String[] names=new String[5];names[4]="Yamaha original · áudio USB";for(int n=0;n<4;n++){String[] presets=service.presetNames(n);int selected=Math.max(0,Math.min(presets.length-1,service.selectedPreset[n]));names[n]="Canal "+(n+1)+" · "+presets[selected];}return names;}
 private void buildControls(){if(!usable()||controls==null)return;rebuilding=true;controls.removeAllViews();ChannelSettings c=settings();spinner(controls,channelNames(),channel,n->{channel=n;buildControls();sync();});spinner(controls,PianoMesh.PARTS,part,this::select);check(controls,"Ver interior (apenas visual)",inside,()->{inside=!inside;sync();saveView();});buttons(controls,button("Vista inicial",()->{yaw=1.1f;pitch=.48f;distance=6.8f;if(piano!=null)piano.camera(yaw,pitch,distance);}),button("Corpo natural",()->{ChannelSettings v=settings();v.bodyEnabled=true;v.bodyAmount=18;v.boardAmount=22;v.bodySize=50;v.boardDamping=50;v.lid=70;service.channelEffects(channel);buildControls();sync();}));check(controls,"Ativar corpo, tábua e tampa",c.bodyEnabled,()->{c.bodyEnabled=!c.bodyEnabled;service.channelEffects(channel);sync();});detail=text(caption(),14,TEAL);controls.addView(detail);
  switch(part){
   case 0:slider("Corpo (%)",100,c.bodyAmount,n->c.bodyAmount=n);slider("Tamanho virtual (%)",100,c.bodySize,n->c.bodySize=n);controls.addView(text("Coloração grave com quatro modos amplos. O tamanho desloca os modos do corpo e da tábua; a escala do desenho é ilustrativa.",12,MUTED));break;
   case 1:slider("Abertura da tampa (%)",100,c.lid,n->c.lid=n);controls.addView(text("Fechar suaviza os agudos; abrir preserva mais brilho. No Yamaha USB, atua no áudio capturado; em Efeitos adicionais colore apenas o retorno. Não altera a tampa física.",12,MUTED));break;
   case 2:slider("Tábua harmônica (%)",100,c.boardAmount,n->c.boardAmount=n);slider("Amortecimento (%)",100,c.boardDamping,n->c.boardDamping=n);controls.addView(text("Doze modos acrescentam vibração ao som. Mais amortecimento encurta essa vibração. Ajuste discreto: o banco já pode conter o corpo do piano.",12,MUTED));break;
   case 3:slider("Ressonância das cordas (%)",100,c.resonance,n->c.resonance=n);controls.addView(text(service.pianoProfileStatus(channel),12,MUTED));if(channel!=4){check(controls,"Usar perfil estimado deste timbre",c.bankProfile,()->{c.bankProfile=!c.bankProfile;service.channelEffects(channel);sync();});controls.addView(button(service.loading?"Aguarde…":"Preparar perfil do timbre",()->service.preparePianoProfile(channel,()->{if(usable()){buildControls();sync();}})));}break;
   case 4:slider("Soltura real · teclas e martelos (%)",100,Math.max(c.hammer,c.keyNoise),n->{c.hammer=c.keyNoise=n;});if(channel!=4){slider("Mistura entre camadas · largura",8,c.blend,n->c.blend=n);check(controls,"Soltura contextual das notas",c.contextual,()->{c.contextual=!c.contextual;service.channelEffects(channel);sync();});}controls.addView(text("Capturas reais da soltura das teclas e retorno dos martelos de um Yamaha C5, tocadas uma única vez por soltura. As transições usam camadas elegíveis do banco.",12,MUTED));break;
   case 5:slider("Detalhe do pedal (%)",100,c.pedalNoise,n->c.pedalNoise=n);check(controls,channel==4?"Ressonância com pedal progressivo":"Pedal progressivo e recaptura",c.pedal,()->{c.pedal=!c.pedal;service.channelEffects(channel);sync();});controls.addView(text(service.synth.pedalDetails(),12,MUTED));controls.addView(text("Valores intermediários dependem do pedal e dos dados MIDI enviados. O desenho mostra a região do controle; não mede o movimento físico.",12,MUTED));break;
  }
  buttons(controls,button("Comparar ligado/desligado",()->{c.bodyEnabled=!c.bodyEnabled;service.channelEffects(channel);buildControls();sync();}),button("Corpo neutro",()->{c.bodyEnabled=false;c.bodyAmount=c.boardAmount=0;c.bodySize=c.boardDamping=50;c.lid=100;service.channelEffects(channel);buildControls();sync();}));controls.addView(text("As cenas guardam os quatro canais; os ajustes Yamaha USB são salvos separadamente e mantidos ao trocar cenas. Girar, aproximar e ver o interior mudam só a visualização. Corpo/tábua são um modelo reduzido de coloração; não uma réplica acústica medida.",11,MUTED));controls.addView(text("Modelo Piano · Bruno Oliveira. Adaptado com 88 teclas, estrutura interna, cordas, ferragens, tampa móvel e pedais. Piano de cauda ilustrativo; não é o P-145BT.",11,MUTED));buttons(controls,button("Créditos do modelo",()->link("https://poly.pizza/m/5vbJ5vildOq")),button("Licença CC BY 3.0",()->link("https://creativecommons.org/licenses/by/3.0/")));rebuilding=false;
 }
 private void link(String url){try{activity.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(ActivityNotFoundException e){Toast.makeText(activity,url,Toast.LENGTH_LONG).show();}}
 private String caption(){ChannelSettings c=settings();String s=PianoMesh.PARTS[part]+" · ";switch(part){case 0:s+=c.bodyAmount+"% · tamanho "+c.bodySize+"%";break;case 1:s+=c.lid+"% aberta";break;case 2:s+=c.boardAmount+"% · amortecimento "+c.boardDamping+"%";break;case 3:s+=c.resonance+"%";break;case 4:s+="soltura real "+Math.max(c.hammer,c.keyNoise)+"%";break;default:s+="ruído "+c.pedalNoise+"%";}if(part<=2&&!c.bodyEnabled)s+=" · efeito desligado";return s;}
 private void sync(){if(!usable())return;if(piano!=null)piano.controls(settings(),part,inside);if(detail!=null)detail.setText(caption());if(indicator!=null){indicator.setContentDescription(caption());indicator.invalidate();}}
 private final class Indicator extends View {
  private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private final float[] point=new float[3];
  Indicator(){super(activity);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_YES);}
  protected void onDraw(Canvas c){if(!usable()||piano==null)return;PianoCamera.State s=piano.state;float pad=dp(12),bottom=getHeight()-dp(14);paint.setColor(0xf2fffffa);c.drawRoundRect(pad,bottom-dp(48),getWidth()-pad,bottom,dp(12),dp(12),paint);paint.setColor(TEAL);paint.setTextSize(dp(12));String str=caption();while(paint.measureText(str)>getWidth()-4*pad&&str.length()>8)str=str.substring(0,str.length()-2)+"…";c.drawText(str,2*pad,bottom-dp(25),paint);paint.setColor(MUTED);paint.setTextSize(dp(10));c.drawText("Parte selecionada • toque no piano ou escolha no menu",2*pad,bottom-dp(10),paint);if(PianoCamera.project(s,PianoMesh.ANCHORS[part],0,part,point)&&point[0]>pad&&point[0]<getWidth()-pad&&point[1]>pad&&point[1]<bottom-dp(54)){paint.setColor(TEAL);paint.setStrokeWidth(dp(2));c.drawLine(point[0],point[1],getWidth()/2f,bottom-dp(48),paint);paint.setColor(0xffedece4);c.drawCircle(point[0],point[1],dp(9),paint);paint.setColor(TEAL);paint.setStyle(Paint.Style.STROKE);c.drawCircle(point[0],point[1],dp(9),paint);paint.setStyle(Paint.Style.FILL);c.drawCircle(point[0],point[1],dp(3),paint);}}
 }
}
